  const [isEditing, setIsEditing] = useState(false);
  const [editId, setEditId] = useState(null);

  // 🟢 Username එකත් ඇතුළත් කරපු State එක
  const [formData, setFormData] = useState({ 
    name: '', 
    username: '', 
    subject: 'O/L - Mathematics', 
    qualifications: '', 
    email: '', 
    phone_number: '', 
    address: '', 
    password: 'TC@123' 
  });

  const [searchQuery, setSearchQuery] = useState('');

  // 🟢 දත්ත ලබා ගැනීම (Read)
  const fetchTeachers = () => {
    axios.get('http://localhost:8081/api/view-teachers')
      .then(res => setTeachers(res.data))
      .catch(err => console.error("Error fetching teachers:", err));
  };

  useEffect(() => { fetchTeachers(); }, []);

  // 🟢 ඇතුළත් කිරීම හෝ Update කිරීම (Create / Update)
  const handleSubmit = (e) => {
    e.preventDefault();

    if (isEditing) {
      // Update කිරීම
      axios.put(`http://localhost:8081/api/update-teacher/${editId}`, formData)
        .then(res => {
          fetchTeachers();
          resetForm();
          alert("✅ Teacher Details Updated Successfully!");
        })
        .catch(err => {
          console.error(err);
          alert("Error updating. Ensure backend PUT route exists.");
        });
    } else {
      // අලුතින් ඇතුළත් කිරීම
      axios.post('http://localhost:8081/api/add-teacher', formData)
        .then(res => {
          if(res.data.status === "Success") {
            fetchTeachers();
            resetForm();
            alert("✅ Teacher Registered Successfully!");
          }
        })
        .catch(err => console.error("Error saving data:", err));
    }
  };

  // 🟢 Delete කිරීම
  const handleDelete = (id) => {
    if(window.confirm("Are you sure you want to remove this teacher?")) {
      axios.delete(`http://localhost:8081/api/delete-teacher/${id}`)
        .then(res => {
          fetchTeachers();
          alert("🗑️ Teacher Removed!");
        })
        .catch(err => {
            console.error(err);
            alert("Error deleting. Ensure backend DELETE route exists.");
            setTeachers(teachers.filter(t => t.id !== id)); 
        });
    }
  };

  // 🟢 Edit Button එක Click කළාම
  const handleEdit = (teacher) => {
    setIsEditing(true);
    setEditId(teacher.id);
    setFormData({
      name: teacher.name,
      username: teacher.username || '',
      subject: teacher.subject,
      qualifications: teacher.qualifications || '',
      email: teacher.email || '',
      phone_number: teacher.phone_number,
      address: teacher.address || '',
      password: teacher.password || 'TC@123'
    });
    setShowForm(true);
  };

  // 🟢 Form එක හිස් කිරීම
  const resetForm = () => {
    setShowForm(false);
    setIsEditing(false);
    setEditId(null);
    setFormData({ name: '', username: '', subject: 'O/L - Mathematics', qualifications: '', email: '', phone_number: '', address: '', password: 'TC@123' });
  };

  const filteredTeachers = [...teachers]
    .reverse()
    .filter(t => 
      t.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
      t.subject.toLowerCase().includes(searchQuery.toLowerCase()) ||
      t.phone_number.includes(searchQuery)
    );

  return (
    <div style={{ padding: '10px', fontFamily: 'sans-serif', animation: 'fadeIn 0.5s' }}>
      
      {/* 🟢 Header & Search */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '25px', backgroundColor: '#fff', padding: '15px 20px', borderRadius: '12px', boxShadow: '0 2px 8px rgba(0,0,0,0.02)', flexWrap: 'wrap', gap: '15px' }}>
        <h2 style={{ margin: 0, color: '#1e293b', fontSize: '22px' }}>🧑‍🏫 Manage Teachers</h2>
        
        <div style={{ display: 'flex', gap: '15px', alignItems: 'center' }}>
          <input 
            type="text" 
            placeholder="Search Name, Subject or Phone..." 
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            style={{ padding: '8px 15px', borderRadius: '8px', border: '1px solid #cbd5e1', outline: 'none', width: '280px', fontSize: '13px' }}
          />
          
          <button 
            onClick={() => { resetForm(); setShowForm(true); }} 
            style={{ padding: '8px 15px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px', boxShadow: '0 4px 10px rgba(21,128,61,0.2)' }}>
            + Add New Teacher
          </button>
        </div>
      </div>

      {/* 🟢 Teachers Table */}
      <div style={{ backgroundColor: '#fff', borderRadius: '12px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)', overflow: 'hidden' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
          <thead>
            <tr style={{ backgroundColor: '#f8fafc', borderBottom: '2px solid #e2e8f0' }}>
              <th style={thStyle}>No.</th>
              <th style={thStyle}>Teacher Info</th>
              <th style={thStyle}>Teaching Subject</th>
              <th style={thStyle}>Qualifications</th>
              <th style={thStyle}>Contact Details</th>
              <th style={{...thStyle, textAlign: 'center'}}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {filteredTeachers.length > 0 ? filteredTeachers.map((t, index) => (
              <tr key={t.id} style={{ borderBottom: '1px solid #f1f5f9', transition: '0.2s' }}>
                <td style={{...tdStyle, fontWeight: 'bold', color: '#1e293b'}}>{index + 1}</td>
                <td style={tdStyle}>
                    <div style={{ fontWeight: 'bold', color: '#15803d', fontSize: '15px' }}>{t.name}</div>
                    <div style={{ fontSize: '12px', color: '#64748b' }}>Username: {t.username || 'Not Set'}</div>
                </td>
                <td style={tdStyle}>
                  <span style={{ backgroundColor: '#f1f5f9', padding: '5px 10px', borderRadius: '6px', fontSize: '12px', fontWeight: 'bold', color: '#475569' }}>
                    {t.subject}
                  </span>
                </td>
                <td style={{...tdStyle, color: '#64748b', fontSize: '13px'}}>{t.qualifications ? t.qualifications : 'N/A'}</td>
                <td style={tdStyle}>
                  <div style={{ fontWeight: 'bold', color: '#475569', fontSize: '13px' }}>📞 {t.phone_number}</div>
                  {t.email && <div style={{ fontSize: '12px', color: '#64748b' }}>✉️ {t.email}</div>}
                  <div style={{ fontSize: '12px', color: '#94a3b8' }}>{t.address ? t.address : 'No Address'}</div>
                </td>
                <td style={{...tdStyle, textAlign: 'center'}}>
                  <button onClick={() => handleEdit(t)} style={{ border: 'none', background: 'none', cursor: 'pointer', fontSize: '16px', marginRight: '10px' }}>✏️</button>
                  <button onClick={() => handleDelete(t.id)} style={{ border: 'none', background: 'none', cursor: 'pointer', fontSize: '16px' }}>🗑️</button>
                </td>
              </tr>
            )) : (
              <tr>
                <td colSpan="6" style={{ padding: '30px', textAlign: 'center', color: '#94a3b8' }}>
                  No teachers found.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* 🟢 Add / Edit Modal Form */}
      {showForm && (
        <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', backgroundColor: 'rgba(0,0,0,0.4)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 1000 }}>
          <div style={{ backgroundColor: 'white', padding: '30px', borderRadius: '15px', width: '500px', boxShadow: '0 10px 25px rgba(0,0,0,0.1)', maxHeight: '90vh', overflowY: 'auto' }}>
            
            <h3 style={{ margin: '0 0 20px 0', color: '#1e293b', fontSize: '20px', borderBottom: '1px solid #f1f5f9', paddingBottom: '10px' }}>
                {isEditing ? '✏️ Edit Teacher Details' : '➕ Add New Teacher'}
            </h3>
            
            <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
              
              <div style={{ display: 'flex', gap: '15px' }}>
                  <input type="text" placeholder="Teacher Full Name" value={formData.name} onChange={(e) => setFormData({...formData, name: e.target.value})} required style={{...inputStyle, flex: 1}} />
                  {/* 🟢 Username Field එක */}
                  <input type="text" placeholder="Username (For Login)" value={formData.username} onChange={(e) => setFormData({...formData, username: e.target.value})} required style={{...inputStyle, flex: 1}} />
              </div>
              
              <select value={formData.subject} onChange={(e) => setFormData({...formData, subject: e.target.value})} style={inputStyle}>
                <option value="O/L - Mathematics">O/L - Mathematics</option>
                <option value="O/L - Science">O/L - Science</option>
                <option value="O/L - Sinhala">O/L - Sinhala</option>
                <option value="O/L - English">O/L - English</option>
                <option value="A/L - Business Studies">A/L - Business Studies</option>
                <option value="A/L - Accounting">A/L - Accounting</option>
                <option value="A/L - Physics">A/L - Physics</option>
                <option value="A/L - ICT">A/L - ICT</option>
              </select>
              
              <input type="text" placeholder="Qualifications (e.g. B.Sc, PGDE)" value={formData.qualifications} onChange={(e) => setFormData({...formData, qualifications: e.target.value})} style={inputStyle} />
              
              <input type="email" placeholder="Email Address (Optional)" value={formData.email} onChange={(e) => setFormData({...formData, email: e.target.value})} style={inputStyle} />
              
              <input type="text" placeholder="Contact Number" value={formData.phone_number} onChange={(e) => setFormData({...formData, phone_number: e.target.value})} required style={inputStyle} />
              
              <input type="text" placeholder="Residence Address (Optional)" value={formData.address} onChange={(e) => setFormData({...formData, address: e.target.value})} style={inputStyle} />
              
              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '12px', marginTop: '10px' }}>
                <button type="button" onClick={resetForm} style={{ padding: '10px 20px', backgroundColor: '#f1f5f9', color: '#475569', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px' }}>Cancel</button>
                <button type="submit" style={{ padding: '10px 25px', backgroundColor: isEditing ? '#3b82f6' : '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px', boxShadow: '0 4px 10px rgba(0,0,0,0.1)' }}>
                    {isEditing ? 'Update Teacher' : 'Save Teacher'}
                </button>
              </div>
            </form>

          </div>
        </div>
      )}
    </div>
  );
}

// Styles
const inputStyle = { padding: '10px 15px', borderRadius: '8px', border: '1px solid #cbd5e1', fontSize: '14px', outline: 'none', width: '100%', boxSizing: 'border-box' };
const thStyle = { padding: '15px', color: '#475569', fontSize: '14px', textAlign: 'left' };
const tdStyle = { padding: '15px', fontSize: '14px' };
